package com.mengzhihua.crm.sales.service;
import com.mengzhihua.crm.common.*; import com.mengzhihua.crm.sales.entity.*; import com.mengzhihua.crm.sales.repository.*; import com.mengzhihua.crm.service.repository.CrmCaseRepository;
import org.springframework.stereotype.Service; import java.util.*;
@Service public class AccountService {private final AccountRepository repo;private final ContactRepository contacts;private final OpportunityRepository opportunities;private final CrmCaseRepository cases;public AccountService(AccountRepository r,ContactRepository c,OpportunityRepository o,CrmCaseRepository ca){repo=r;contacts=c;opportunities=o;cases=ca;}public PageResult<Account> list(int page,int size,String k){return DtoUtil.page(k==null||k.isEmpty()?repo.findAll(DtoUtil.pageable(page,size)):repo.findByNameContainingIgnoreCase(k,DtoUtil.pageable(page,size)),x->(Account)x);}public Account get(Long id){return repo.findById(id).orElseThrow(()->new BizException("客户不存在"));}public Account save(Account a){if(a.getName()==null||a.getName().trim().isEmpty())throw new BizException("客户名称不能为空");if(a.getId()==null&&repo.existsByNameIgnoreCase(a.getName()))throw new BizException("客户名称已存在");return repo.save(a);}public void delete(Long id){repo.deleteById(id);}public Map<String,Object> overview(Long id){Map<String,Object> m=new LinkedHashMap<>();m.put("account",get(id));m.put("contacts",contacts.findByAccountId(id));m.put("opportunities",opportunities.findByAccountId(id));m.put("cases",cases.findByAccountId(id));return m;}}
